import pandas as pd
import matplotlib.pyplot as plt
import base64
from io import BytesIO
import seaborn as sns

def get_base64_image(fig):
    buf = BytesIO()
    fig.savefig(buf, format="png", bbox_inches="tight")
    plt.close(fig)
    buf.seek(0)
    img_b64 = base64.b64encode(buf.read()).decode("utf-8")
    return f"data:image/png;base64,{img_b64}"

def main():
    # Load data
    df = pd.read_csv('/app/benchmark/data.csv')
    df['Sale_Date'] = pd.to_datetime(df['Sale_Date'])

    # KPIs
    avg_profit_margin = df['Profit_Margin_USD'].mean()
    resale_premium_rate = (df['Resale_Price_USD'] > df['Retail_Price_USD']).mean()
    avg_days_in_inventory = df['Days_in_Inventory'].mean()
    avg_resale_to_retail = (df['Resale_Price_USD'] / df['Retail_Price_USD']).mean()

    colorway_margins = df.groupby('Colorway')['Profit_Margin_USD'].mean()
    top_colorway = colorway_margins.idxmax()
    top_colorway_margin = colorway_margins.max()

    # 1. Market Overview
    fig1, ax1 = plt.subplots(figsize=(10, 5))
    sns.histplot(df['Profit_Margin_USD'], bins=50, ax=ax1, kde=True, color='skyblue')
    ax1.set_title('Distribution of Profit Margins (USD)')
    ax1.set_xlabel('Profit Margin (USD)')
    ax1.set_ylabel('Frequency')
    img1 = get_base64_image(fig1)

    # 2. Performance by Shoe Model & Colorway
    fig2, (ax2a, ax2b) = plt.subplots(1, 2, figsize=(16, 6))
    model_perf = df.groupby('Shoe_Model')['Profit_Margin_USD'].mean().sort_values(ascending=False)
    sns.barplot(x=model_perf.values, y=model_perf.index, ax=ax2a, palette='viridis')
    ax2a.set_title('Avg Profit Margin by Shoe Model')
    ax2a.set_xlabel('Avg Profit Margin (USD)')

    colorway_perf = df.groupby('Colorway')['Profit_Margin_USD'].mean().sort_values(ascending=False)
    sns.barplot(x=colorway_perf.values, y=colorway_perf.index, ax=ax2b, palette='magma')
    ax2b.set_title('Avg Profit Margin by Colorway')
    ax2b.set_xlabel('Avg Profit Margin (USD)')
    img2 = get_base64_image(fig2)

    # 3. Impact of Shoe Condition
    fig3, ax3 = plt.subplots(figsize=(10, 5))
    sns.boxplot(x='Condition', y='Profit_Margin_USD', data=df, ax=ax3, order=['Deadstock (Brand New)', 'VNDS (Very Near Deadstock)', 'Used'], palette='Set2')
    ax3.set_title('Profit Margin by Shoe Condition')
    ax3.set_ylabel('Profit Margin (USD)')
    img3 = get_base64_image(fig3)

    # 4. Sales Channel Performance & Inventory Velocity
    fig4, ax4 = plt.subplots(figsize=(10, 6))
    channel_agg = df.groupby('Sales_Channel').agg({'Profit_Margin_USD': 'mean', 'Days_in_Inventory': 'mean'}).reset_index()
    sns.scatterplot(x='Days_in_Inventory', y='Profit_Margin_USD', hue='Sales_Channel', s=200, data=channel_agg, ax=ax4, palette='deep')
    for i, row in channel_agg.iterrows():
        ax4.text(row['Days_in_Inventory'] + 0.5, row['Profit_Margin_USD'], row['Sales_Channel'], fontsize=10)
    ax4.set_title('Channel Performance: Margin vs Inventory Velocity')
    ax4.set_xlabel('Average Days in Inventory')
    ax4.set_ylabel('Average Profit Margin (USD)')
    img4 = get_base64_image(fig4)

    # 5. Temporal Trends & Seasonality
    fig5, ax5 = plt.subplots(figsize=(12, 5))
    monthly_trend = df.set_index('Sale_Date').resample('ME')['Profit_Margin_USD'].mean()
    monthly_trend.plot(ax=ax5, color='coral', marker='o')
    ax5.set_title('Monthly Average Profit Margin (2023-2026)')
    ax5.set_ylabel('Avg Profit Margin (USD)')
    ax5.set_xlabel('Date')
    ax5.grid(True)
    img5 = get_base64_image(fig5)

    # Generate HTML
    html = f"""
    <!DOCTYPE html>
    <html lang="en">
    <head>
        <meta charset="UTF-8">
        <title>Air Jordan Sneaker Resale Market Analysis (2023–2026)</title>
        <style>
            :root {{
                --bg-color: #f8fafc;
                --text-color: #1e293b;
                --card-bg: #ffffff;
                --accent-color: #2563eb;
                --border-color: #e2e8f0;
            }}
            body {{
                font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
                background-color: var(--bg-color);
                color: var(--text-color);
                line-height: 1.6;
                margin: 0;
                padding: 40px;
            }}
            .container {{
                max-width: 1200px;
                margin: 0 auto;
            }}
            h1, h2, h3 {{
                color: #0f172a;
            }}
            h1 {{
                text-align: center;
                font-size: 2.5em;
                margin-bottom: 10px;
            }}
            .subtitle {{
                text-align: center;
                font-size: 1.2em;
                color: #64748b;
                margin-bottom: 40px;
            }}
            .kpi-container {{
                display: flex;
                flex-wrap: wrap;
                gap: 20px;
                margin-bottom: 40px;
                justify-content: center;
            }}
            .kpi-card {{
                background: var(--card-bg);
                padding: 20px;
                border-radius: 10px;
                box-shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.1);
                flex: 1;
                min-width: 200px;
                text-align: center;
                border: 1px solid var(--border-color);
            }}
            .kpi-value {{
                font-size: 2em;
                font-weight: bold;
                color: var(--accent-color);
                margin-bottom: 5px;
            }}
            .kpi-label {{
                font-size: 0.9em;
                color: #64748b;
                text-transform: uppercase;
                letter-spacing: 0.05em;
            }}
            .section {{
                background: var(--card-bg);
                padding: 30px;
                border-radius: 10px;
                box-shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.1);
                margin-bottom: 40px;
                border: 1px solid var(--border-color);
            }}
            .chart-container {{
                text-align: center;
                margin-top: 20px;
            }}
            img {{
                max-width: 100%;
                height: auto;
                border-radius: 5px;
            }}
            table {{
                width: 100%;
                border-collapse: collapse;
                margin-top: 20px;
            }}
            th, td {{
                border: 1px solid var(--border-color);
                padding: 12px;
                text-align: left;
            }}
            th {{
                background-color: #f1f5f9;
                font-weight: 600;
            }}
            .recommendations ul {{
                padding-left: 20px;
            }}
            .recommendations li {{
                margin-bottom: 10px;
            }}
        </style>
    </head>
    <body>
        <div class="container">
            <h1>Air Jordan Sneaker Resale Market Analysis</h1>
            <div class="subtitle">2023–2026 Secondary-Market Transactions</div>

            <div class="kpi-container">
                <div class="kpi-card">
                    <div class="kpi-value">${avg_profit_margin:.2f}</div>
                    <div class="kpi-label">Avg Profit Margin</div>
                </div>
                <div class="kpi-card">
                    <div class="kpi-value">{resale_premium_rate:.1%}</div>
                    <div class="kpi-label">Resale Premium Rate</div>
                </div>
                <div class="kpi-card">
                    <div class="kpi-value">{avg_days_in_inventory:.1f}</div>
                    <div class="kpi-label">Avg Days in Inventory</div>
                </div>
                <div class="kpi-card">
                    <div class="kpi-value">{avg_resale_to_retail:.2f}x</div>
                    <div class="kpi-label">Resale-to-Retail Ratio</div>
                </div>
                <div class="kpi-card">
                    <div class="kpi-value">${top_colorway_margin:.2f}</div>
                    <div class="kpi-label">Top Colorway Margin ({top_colorway})</div>
                </div>
            </div>

            <div class="section">
                <h2>1. Market Overview & Transaction Summary</h2>
                <p>This analysis covers 5,000 synthetic secondary-market transactions of Air Jordan sneakers between 2023 and 2026. The data encompasses various models, conditions, and sales channels, providing a comprehensive view of the resale landscape.</p>
                <div class="chart-container">
                    <img src="{img1}" alt="Profit Margin Distribution">
                </div>
            </div>

            <div class="section">
                <h2>2. Performance by Shoe Model & Colorway</h2>
                <p>Certain silhouettes and colorways command significant premiums on the secondary market. The charts below rank models and colorways by their average profit margins, highlighting the most lucrative segments for sourcing.</p>
                <div class="chart-container">
                    <img src="{img2}" alt="Performance by Model and Colorway">
                </div>
            </div>

            <div class="section">
                <h2>3. Impact of Shoe Condition on Resale Value</h2>
                <p>The physical state of a shoe heavily influences its resale price. Deadstock (Brand New) condition typically guarantees a premium, while Used pairs frequently sell below the original retail price.</p>
                <div class="chart-container">
                    <img src="{img3}" alt="Condition Impact">
                </div>
            </div>

            <div class="section">
                <h2>4. Sales Channel Performance & Inventory Velocity</h2>
                <p>Analyzing the interplay between margin and turnover speed across different platforms. The ideal channel maximizes profit margin while minimizing the days a shoe sits in inventory.</p>
                <div class="chart-container">
                    <img src="{img4}" alt="Channel Performance">
                </div>
            </div>

            <div class="section">
                <h2>5. Temporal Trends & Seasonality</h2>
                <p>Monthly trends in average profit margins from 2023 to 2026, surfacing potential seasonality and momentum shifts in the Air Jordan resale market.</p>
                <div class="chart-container">
                    <img src="{img5}" alt="Temporal Trends">
                </div>
            </div>

            <div class="section recommendations">
                <h2>6. Key Findings & Strategic Recommendations</h2>
                <ul>
                    <li><strong>Sourcing Priority:</strong> Focus acquisition efforts on top-performing colorways like <em>{top_colorway}</em>, which yield the highest average margins.</li>
                    <li><strong>Condition Constraints:</strong> Prioritize <em>Deadstock</em> and <em>VNDS</em> inventory. Used pairs pose a higher risk of negative margins and should be acquired only at significant discounts to retail.</li>
                    <li><strong>Channel Optimization:</strong> Allocate inventory based on channel velocity and margin tradeoffs. High-margin platforms with slower velocity are better for highly sought-after pairs, whereas faster channels can be used for liquidating lower-margin inventory.</li>
                    <li><strong>Timing:</strong> Monitor the temporal trends to identify peak selling seasons and adjust holding strategies accordingly to maximize returns.</li>
                </ul>
            </div>
        </div>
    </body>
    </html>
    """

    with open('/app/output/final_report.html', 'w') as f:
        f.write(html)

    print("Report generated at /app/output/final_report.html")

if __name__ == '__main__':
    main()
